/**
 * Reducer cases of the open draft formats (DESIGN "Specification: card data, packs and draft formats", Draft formats:
 * Rochester, Winston, Grid; "Pre-game", Hidden information column). Called through core/reducer/drafting.ts.
 * Contracts: M2-C (stubs); implementer: M2-P3. The turn rules are core/open.ts.
 *
 * Every pack is generated by its opener's browser from a secret-shuffle seed (purpose 'pack', DESIGN "Specification:
 * network protocol and secrecy", Draft packs): `packOpen` names the sealed round (`sid`) and publishes the
 * commitments of the pack's sorted opaque ids.
 *
 * - Rochester and Grid packs are public (`public: true`): the action carries every card with its salt, each must open
 *   one of the commitments, and the cards lie face up in shared state (the Rochester pack in pack order; a grid in the
 *   order given, at most nine cells). Picks name the card; picked ids are listed per drafter in `DraftState.taken`.
 * - Winston packs stay hidden: commitments and opaque ids only. The dealer opens them all; the last `packOpen` deals
 *   the stack (core/open.ts `winstonDeal`). Shared state then holds the opaque ids of the stack and piles and of what
 *   each player took; identities stay with the dealer, who shows a pile to the other player on the pair channel
 *   (`draftCards`, net/draftcards.ts) only while that player looks at it (DECISIONS [M2-P3]).
 *
 * Pure and total like the rest of the reducer.
 */
import type { ActionOf } from '../actions';
import { commitFor } from '../commit';
import { setForPack } from '../drafting';
import {
  GRID_SIDE,
  gridAnyLineOpen,
  gridLine,
  gridLineOpen,
  gridTaker,
  nextPile,
  otherDrafter,
  rochesterPicker,
  rochesterRound,
  rochesterTotal,
  winstonDeal,
  winstonDealt,
  winstonStep,
} from '../open';
import { shuffleReady } from '../rng';
import type { DraftCard, DraftFormat, DraftPack, DraftState, GridSettings, InstanceId, PackId, RochesterSettings, SeatId, WinstonSettings } from '../types';
import type { Draft } from './draft';
import { checkId, checkInt, checkRef, checkString, isObj, own, reject } from './util';

/** Most cards one pack may hold (real boosters hold at most about twenty). */
const MAX_PACK_CARDS = 64;
/** Longest commit or salt string accepted. */
const MAX_SECRET = 256;
const GRID_CELL_COUNT = GRID_SIDE * GRID_SIDE;

/** The seq this action gets: its own once sequenced, else the next one (an optimistic copy). */
function seqOf(d: Draft, a: { seq?: number }): number {
  return a.seq ?? d.base.seq + 1;
}

/** The running draft of format `format`, writable; refuses outside the draft stage, after the end, or in another format. */
function running(d: Draft, format: DraftFormat): DraftState {
  const cur = d.draft;
  if (cur === null) reject('no draft is in progress');
  if (d.base.stage !== 'draft') reject('the table is not in the draft stage');
  if (cur.settings.format !== format) reject(`this is a ${cur.settings.format} draft, not ${format}`);
  if (cur.done) reject('the draft is over');
  return d.draftW();
}

function checkDrafter(draft: DraftState, by: unknown): SeatId {
  const seat = checkId(by, 'seat');
  if (!draft.drafters.includes(seat)) reject(`${seat} is not drafting`);
  return seat;
}

function takenOf(draft: DraftState, seat: SeatId): InstanceId[] {
  draft.taken ??= {};
  for (const s of draft.drafters) draft.taken[s] ??= [];
  return draft.taken[seat]!;
}

/** Every instance id some pack of this draft committed to. */
function usedIds(draft: DraftState): Set<InstanceId> {
  const out = new Set<InstanceId>();
  for (const p of Object.values(draft.packs)) for (const id of p.commitment.instanceIds) out.add(id);
  return out;
}

/** The checked public part of a `packOpen`: a new pack of `by` from a sealed pack-seed round of `by`. */
interface OpenedPack {
  packId: PackId;
  ids: InstanceId[];
  commits: string[];
  number: number;
  set: string;
}

function checkPackOpen(d: Draft, draft: DraftState, by: SeatId, a: ActionOf<'packOpen'>): OpenedPack {
  const packId = checkId(a.packId, 'pack');
  if (own(draft.packs, packId)) reject(`pack ${packId} is already open`);
  const count = checkInt(a.count, 'pack size', 0, MAX_PACK_CARDS);
  if (!Array.isArray(a.commits) || !Array.isArray(a.instanceIds)) reject('a pack needs its commitments and opaque ids');
  const commits = (a.commits as unknown[]).map((c) => checkString(c, 'commit', MAX_SECRET));
  const ids = (a.instanceIds as unknown[]).map((id) => checkId(id, 'card'));
  if (commits.length !== count || ids.length !== count) reject(`a pack of ${count} cards needs ${count} commitments and ids`);
  // Sorted, so neither list says anything about the pack order (rare first) or which id is which card.
  for (let i = 1; i < ids.length; i++) if (!(ids[i - 1]! < ids[i]!)) reject('pack ids must be sorted and unique');
  for (let i = 1; i < commits.length; i++) if (commits[i - 1]! > commits[i]!) reject('pack commitments must be sorted');
  const used = usedIds(draft);
  for (const id of ids) {
    if (used.has(id) || d.cards.has(id)) reject(`card id ${id} is already in use`);
  }
  // The pack was generated from a secret-shuffle seed its opener could not choose (DESIGN "Draft packs").
  const sid = checkId(a.sid, 'shuffle');
  const round = own(d.base.shuffles, sid);
  if (!round || round.purpose !== 'pack') reject(`${sid} is not a pack-seed round`);
  if (round.owner !== by) reject(`pack-seed round ${sid} belongs to ${round.owner}`);
  if (round.orderHash === null && !shuffleReady(d.base, sid)) reject(`pack-seed round ${sid} still waits for peer nonces`);
  const number = checkInt(a.number, 'pack number', 0, 1000);
  const set = checkString(a.set, 'set code', 16);
  if (set !== setForPack(draft.sets, number)) reject(`pack ${number + 1} is of set ${setForPack(draft.sets, number)}`);
  return { packId, ids, commits, number, set };
}

/** The face-up cards of a public pack, each opening one of its commitments (DESIGN "Commitments"). */
function publicCards(a: ActionOf<'packOpen'>, p: OpenedPack): DraftCard[] {
  if (a.public !== true || !Array.isArray(a.cards)) reject('this pack is opened face up: it needs its cards');
  const cards = a.cards as unknown[];
  if (cards.length !== p.ids.length) reject('a public pack shows every card');
  const ids = new Set(p.ids);
  const commits = new Set(p.commits);
  const out: DraftCard[] = [];
  for (const c of cards) {
    if (!isObj(c)) reject('invalid pack card');
    const id = checkId(c.instanceId, 'card');
    const ref = checkRef(c.ref);
    const salt = checkString(c.salt, 'salt', MAX_SECRET);
    if (!ids.delete(id)) reject(`card ${id} is not one of the pack's ids, or shown twice`);
    if (!commits.has(commitFor(id, ref, salt))) reject(`card ${id} does not open the pack's commitments`);
    out.push({ id, ref });
  }
  return out;
}

function recordPack(draft: DraftState, by: SeatId, p: OpenedPack, seq: number, cards?: DraftCard[]): DraftPack {
  const pack: DraftPack = {
    id: p.packId,
    opener: by,
    number: p.number,
    set: p.set,
    commitment: { seat: by, commits: [...p.commits], instanceIds: [...p.ids], atSeq: seq },
    count: p.ids.length,
    holder: null,
    picks: 0,
    sinceSeq: seq,
    ...(cards !== undefined ? { cards } : {}),
  };
  draft.packs[p.packId] = pack;
  return pack;
}

/** `packOpen` of an open format (see the module comment). */
export function packOpen(d: Draft, a: ActionOf<'packOpen'>): void {
  const format = d.draft?.settings.format;
  if (format === 'rochester') return rochesterOpen(d, a);
  if (format === 'winston') return winstonOpen(d, a);
  if (format === 'grid') return gridOpen(d, a);
  reject(`packOpen does not apply to a ${format ?? 'missing'} draft`);
}

/** `pick`: Rochester only (Winston uses `pileLook`, Grid `gridTake`). */
export function pick(d: Draft, a: ActionOf<'pick'>): void {
  const format = d.draft?.settings.format;
  if (format === 'winston') reject('a Winston draft takes piles with pileLook');
  if (format === 'grid') reject('a grid draft takes lines with gridTake');
  rochesterPick(d, a);
}

// ---- Rochester ----------------------------------------------------------------------------------------------------

function rochesterOpen(d: Draft, a: ActionOf<'packOpen'>): void {
  const draft = running(d, 'rochester');
  const by = checkDrafter(draft, a.by);
  const r = draft.rochester;
  if (r === undefined) reject('the Rochester state is missing');
  if (r.pack !== null) reject(`pack ${r.pack} is still on the table`);
  if (r.opened >= rochesterTotal(draft)) reject('every pack is open');
  if (by !== r.opener) reject(`${r.opener} opens the next pack`);
  const p = checkPackOpen(d, draft, by, a);
  const round = rochesterRound(r.opened, draft.drafters.length);
  if (p.number !== round) reject(`the next pack is pack ${round + 1}`);
  const cards = publicCards(a, p);
  const seq = seqOf(d, a);
  recordPack(draft, by, p, seq, cards);
  takenOf(draft, by);
  r.pack = p.packId;
  r.turn = 0;
  r.opened += 1;
  draft.round = round;
  rochesterMaybeFinish(draft);
}

/** Once `burn` cards (or fewer) remain, the pack leaves the table and the opener role moves left (DESIGN Rochester). */
function rochesterMaybeFinish(draft: DraftState): void {
  const r = draft.rochester!;
  const pack = draft.packs[r.pack!]!;
  const burn = (draft.settings as RochesterSettings).burn;
  if (pack.count > burn) return;
  r.pack = null;
  r.turn = 0;
  if (r.opened >= rochesterTotal(draft)) {
    draft.done = true;
    return;
  }
  const i = draft.drafters.indexOf(r.opener);
  r.opener = draft.drafters[(i + 1) % draft.drafters.length]!;
}

function rochesterPick(d: Draft, a: ActionOf<'pick'>): void {
  const draft = running(d, 'rochester');
  const by = checkDrafter(draft, a.by);
  const r = draft.rochester;
  if (r === undefined || r.pack === null) reject('no pack is on the table');
  const packId = checkId(a.packId, 'pack');
  if (packId !== r.pack) reject(`pack ${packId} is not the pack on the table`);
  const picker = rochesterPicker(draft);
  if (by !== picker) reject(`it is ${picker}'s pick`);
  checkInt(a.count, 'pick count', 1, 1);
  if (!Array.isArray(a.cards) || a.cards.length !== 1) reject('a Rochester pick names exactly one card');
  const id = checkId(a.cards[0], 'card');
  const pack = draft.packs[packId]!;
  const cards = pack.cards ?? [];
  const at = cards.findIndex((c) => c.id === id);
  if (at < 0) reject(`card ${id} is not in pack ${packId}`);
  cards.splice(at, 1);
  pack.cards = cards;
  pack.count -= 1;
  pack.picks += 1;
  pack.sinceSeq = seqOf(d, a);
  draft.pools[by] = (draft.pools[by] ?? 0) + 1;
  takenOf(draft, by).push(id);
  r.turn += 1;
  rochesterMaybeFinish(draft);
}

// ---- Winston ------------------------------------------------------------------------------------------------------

function twoSeats(draft: DraftState, format: string): void {
  if (draft.drafters.length !== 2) reject(`a ${format} draft is for two seats`);
}

function winstonOpen(d: Draft, a: ActionOf<'packOpen'>): void {
  const draft = running(d, 'winston');
  twoSeats(draft, 'Winston');
  const by = checkDrafter(draft, a.by);
  const w = draft.winston;
  if (w === undefined) reject('the Winston state is missing');
  if (winstonDealt(w)) reject('the stack is already dealt');
  if (by !== w.dealer) reject(`${w.dealer} deals the Winston stack`);
  // The stack is face down: no identity may enter shared state.
  if (a.public === true || a.cards !== undefined) reject('Winston packs stay face down');
  const p = checkPackOpen(d, draft, by, a);
  const total = (draft.settings as WinstonSettings).packs;
  const opened = Object.keys(draft.packs).length;
  if (p.number !== opened) reject(`the next pack is pack ${opened + 1}`);
  recordPack(draft, by, p, seqOf(d, a));
  if (opened + 1 < total) return;
  // Every pack is open: deal the stack (core/open.ts winstonDeal).
  const all = Object.values(draft.packs).flatMap((x) => x.commitment.instanceIds);
  const dealt = winstonDeal(all);
  w.stackIds = dealt.stackIds;
  w.pileIds = dealt.pileIds;
  w.stack = dealt.stackIds.length;
  w.piles = dealt.pileIds.map((x) => x.length);
  for (const pack of Object.values(draft.packs)) pack.count = 0;
  for (const s of draft.drafters) takenOf(draft, s);
  w.pile = nextPile(w.piles, 0);
  if (w.pile < 0) {
    w.pile = 0;
    draft.done = true;
  }
}

/** `pileLook {pile, take}`: the active player takes the pile looked at, or declines it (core/open.ts `winstonStep`). */
export function pileLook(d: Draft, a: ActionOf<'pileLook'>): void {
  const draft = running(d, 'winston');
  twoSeats(draft, 'Winston');
  const by = checkDrafter(draft, a.by);
  const w = draft.winston;
  if (!winstonDealt(w)) reject('the stack is not dealt yet');
  if (by !== w.active) reject(`it is ${w.active}'s turn`);
  const pile = checkInt(a.pile, 'pile', 0, 2);
  if (pile !== w.pile) reject(`${w.active} is looking at pile ${w.pile + 1}`);
  if (typeof a.take !== 'boolean') reject('take must be true or false');
  const step = winstonStep(w, a.take);
  if (typeof step === 'string') reject(step);
  w.stackIds = step.stackIds;
  w.pileIds = step.pileIds;
  w.stack = step.stackIds.length;
  w.piles = step.pileIds.map((x) => x.length);
  takenOf(draft, by).push(...step.taken);
  draft.pools[by] = (draft.pools[by] ?? 0) + step.taken.length;
  if (!step.turnOver) {
    w.pile = step.pile;
    return;
  }
  w.active = otherDrafter(draft, by);
  const next = nextPile(w.piles, 0);
  if (next < 0) {
    // Piles are refilled while the stack lasts, so empty piles mean an empty stack: the draft is over.
    w.pile = 0;
    draft.done = true;
  } else {
    w.pile = next;
  }
}

// ---- Grid ---------------------------------------------------------------------------------------------------------

function gridOpen(d: Draft, a: ActionOf<'packOpen'>): void {
  const draft = running(d, 'grid');
  twoSeats(draft, 'grid');
  const by = checkDrafter(draft, a.by);
  const g = draft.grid;
  if (g === undefined) reject('the grid state is missing');
  if (g.cells.length > 0) reject(`grid ${g.index + 1} is still on the table`);
  if (by !== g.first) reject(`${g.first} lays the next grid`);
  const p = checkPackOpen(d, draft, by, a);
  if (p.ids.length < 1 || p.ids.length > GRID_CELL_COUNT) reject(`a grid holds 1 to ${GRID_CELL_COUNT} cards`);
  if (p.number !== g.index) reject(`the next grid is grid ${g.index + 1}`);
  const cards = publicCards(a, p);
  recordPack(draft, by, p, seqOf(d, a), cards.map((c) => ({ ...c })));
  takenOf(draft, by);
  g.cells = Array.from({ length: GRID_CELL_COUNT }, (_, i) => cards[i] ?? null);
  g.taken = [];
}

/** `gridTake {grid, line, index}`: the first player, then the second; the rest is discarded and the next grid is due. */
export function gridTake(d: Draft, a: ActionOf<'gridTake'>): void {
  const draft = running(d, 'grid');
  twoSeats(draft, 'grid');
  const by = checkDrafter(draft, a.by);
  const g = draft.grid;
  if (g === undefined || g.cells.length === 0) reject('no grid is on the table');
  const index = checkInt(a.grid, 'grid', 0, 1000);
  if (index !== g.index) reject(`grid ${g.index + 1} is on the table`);
  const taker = gridTaker(draft);
  if (by !== taker) reject(`it is ${taker}'s take`);
  if (a.line !== 'row' && a.line !== 'col') reject('take a row or a column');
  const i = checkInt(a.index, 'line index', 0, GRID_SIDE - 1);
  if (!gridLineOpen(g, a.line, i)) reject(`that ${a.line === 'row' ? 'row' : 'column'} is already taken`);
  const ids: InstanceId[] = [];
  for (const cell of gridLine(a.line, i)) {
    const c = g.cells[cell];
    if (c == null) continue;
    ids.push(c.id);
    g.cells[cell] = null;
  }
  const packId = Object.values(draft.packs).find((p) => p.number === g.index)?.id;
  if (packId !== undefined) {
    const pack = draft.packs[packId]!;
    const gone = new Set(ids);
    pack.cards = (pack.cards ?? []).filter((c) => !gone.has(c.id));
    pack.count = pack.cards.length;
    pack.picks += 1;
    pack.sinceSeq = seqOf(d, a);
  }
  takenOf(draft, by).push(...ids);
  draft.pools[by] = (draft.pools[by] ?? 0) + ids.length;
  g.taken.push({ line: a.line, index: i });
  if (g.taken.length < 2 && gridAnyLineOpen(g)) return;
  // The rest is discarded (it stays listed in its pack); the first player alternates for the next grid.
  const grids = (draft.settings as GridSettings).grids;
  g.index += 1;
  g.cells = [];
  g.taken = [];
  if (g.index >= grids) {
    draft.done = true;
    return;
  }
  g.first = otherDrafter(draft, g.first);
}
